//go:build linux

package trace

import (
	"encoding/binary"
	"net"
	"os"
	"time"

	"golang.org/x/net/icmp"
	"golang.org/x/net/ipv4"
	"golang.org/x/sys/unix"
)

// soEEOriginICMP is SO_EE_ORIGIN_ICMP from <linux/errqueue.h>: the queued
// error was generated by an incoming ICMP message.
const soEEOriginICMP = 2

// sizeofSockExtendedErr is sizeof(struct sock_extended_err); the offender's
// sockaddr_in follows it in the IP_RECVERR control message.
const sizeofSockExtendedErr = 16

// protocolICMP is the IANA protocol number for ICMP (used by ParseMessage).
const protocolICMP = 1

// probeHop sends one ICMP echo with the given TTL over an unprivileged ICMP
// datagram socket (allowed by net.ipv4.ping_group_range, no root needed).
//
// Linux never delivers ICMP errors such as Time Exceeded to such a socket via a
// plain read: they go to the socket error queue, and only when IP_RECVERR is
// enabled. So intermediate hops are read with MSG_ERRQUEUE, while the echo reply
// from the destination arrives as normal data. A timeout is loss, not an error.
func probeHop(dst net.IP, ttl int, timeout time.Duration) hopReply {
	dst4 := dst.To4()
	if dst4 == nil {
		return hopReply{err: net.InvalidAddrError("нужен IPv4-адрес")}
	}

	fd, err := unix.Socket(unix.AF_INET, unix.SOCK_DGRAM|unix.SOCK_CLOEXEC, unix.IPPROTO_ICMP)
	if err != nil {
		return hopReply{err: os.NewSyscallError("socket", err)}
	}
	defer unix.Close(fd)

	if err := unix.SetsockoptInt(fd, unix.IPPROTO_IP, unix.IP_TTL, ttl); err != nil {
		return hopReply{err: os.NewSyscallError("setsockopt IP_TTL", err)}
	}
	if err := unix.SetsockoptInt(fd, unix.IPPROTO_IP, unix.IP_RECVERR, 1); err != nil {
		return hopReply{err: os.NewSyscallError("setsockopt IP_RECVERR", err)}
	}

	// The kernel overwrites the echo ID with the socket's own identifier.
	wm := icmp.Message{
		Type: ipv4.ICMPTypeEcho, Code: 0,
		Body: &icmp.Echo{ID: os.Getpid() & 0xffff, Seq: ttl, Data: []byte("speedtest-trace")},
	}
	wb, err := wm.Marshal(nil)
	if err != nil {
		return hopReply{err: err}
	}

	sa := &unix.SockaddrInet4{}
	copy(sa.Addr[:], dst4)
	start := time.Now()
	if err := unix.Sendto(fd, wb, 0, sa); err != nil {
		return hopReply{err: os.NewSyscallError("sendto", err)}
	}

	deadline := start.Add(timeout)
	buf := make([]byte, 1500)
	oob := make([]byte, 512)
	for {
		wait := time.Until(deadline)
		if wait <= 0 {
			return hopReply{}
		}
		pfd := []unix.PollFd{{Fd: int32(fd), Events: unix.POLLIN}}
		n, err := unix.Poll(pfd, int(wait.Milliseconds())+1)
		if err == unix.EINTR {
			continue
		}
		if err != nil {
			return hopReply{err: os.NewSyscallError("poll", err)}
		}
		if n == 0 {
			return hopReply{}
		}
		rtt := time.Since(start)

		// An ICMP error from a router (or the destination) sits in the error queue.
		if pfd[0].Revents&unix.POLLERR != 0 {
			if r, ok := readErrQueue(fd, buf, oob, rtt, dst4); ok {
				return r
			}
			continue
		}

		if pfd[0].Revents&unix.POLLIN != 0 {
			m, from, err := unix.Recvfrom(fd, buf, unix.MSG_DONTWAIT)
			if err != nil {
				continue
			}
			rm, err := icmp.ParseMessage(protocolICMP, buf[:m])
			if err != nil || rm.Type != ipv4.ICMPTypeEchoReply {
				continue
			}
			var ip net.IP = dst4
			if a, ok := from.(*unix.SockaddrInet4); ok {
				ip = net.IP(a.Addr[:]).To4()
			}
			return hopReply{from: ip, rtt: rtt, reached: true}
		}
	}
}

// readErrQueue pops one queued ICMP error and reports the router that sent it.
// Time Exceeded means an intermediate hop; any other ICMP error (for example
// Destination Unreachable) coming from the target itself means it was reached.
func readErrQueue(fd int, buf, oob []byte, rtt time.Duration, dst net.IP) (hopReply, bool) {
	_, oobn, _, _, err := unix.Recvmsg(fd, buf, oob, unix.MSG_ERRQUEUE|unix.MSG_DONTWAIT)
	if err != nil {
		return hopReply{}, false
	}
	msgs, err := unix.ParseSocketControlMessage(oob[:oobn])
	if err != nil {
		return hopReply{}, false
	}
	for _, m := range msgs {
		if m.Header.Level != unix.IPPROTO_IP || m.Header.Type != unix.IP_RECVERR {
			continue
		}
		// struct sock_extended_err (16 bytes), then the offender sockaddr_in.
		d := m.Data
		if len(d) < sizeofSockExtendedErr+unix.SizeofSockaddrInet4 {
			continue
		}
		origin, icmpType := d[4], d[5]
		if origin != soEEOriginICMP {
			continue
		}
		off := d[sizeofSockExtendedErr:]
		if binary.LittleEndian.Uint16(off[0:2]) != unix.AF_INET {
			continue
		}
		from := net.IPv4(off[4], off[5], off[6], off[7]).To4()
		reached := icmpType != uint8(ipv4.ICMPTypeTimeExceeded) && from.Equal(dst)
		return hopReply{from: from, rtt: rtt, reached: reached}, true
	}
	return hopReply{}, false
}
